    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endPAP(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // PAP_ID
        $builder->required($o, 18);  // ELEMENTS
        $builder->required($o, 36);  // GAIN_CUTS
        $builder->required($o, 54);  // PROVENANCE
        $builder->required($o, 58);  // PRODUCER_ID
        $builder->required($o, 60);  // SIGNATURE
        $builder->required($o, 62);  // CANONICAL_JSON_SIGNATURE
        return $o;
    }

    public static function finishPAPBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$PAP");
    }
